#!/bin/bash
# Generate test cases for Domain H (hue branch coverage), one "y u v" per line.
# YUV->RGB: r = y + 1.14v, g = y - 0.395u - 0.581v, b = y + 2.032u

# 1) Full grid: u,v in {-2,-1.5,-1,-0.5,-0.1,0,0.1,0.5,1,1.5,2} x y in {-1,0,0.5,1,2}
for y in -1 0 0.5 1 2; do
  for u in -2 -1.5 -1 -0.5 -0.1 0 0.1 0.5 1 1.5 2; do
    for v in -2 -1.5 -1 -0.5 -0.1 0 0.1 0.5 1 1.5 2; do
      echo "$y $u $v"
    done
  done
done

# 2) Grid with y varying and u == v
for y in -2 -1.5 -1 -0.5 -0.1 0 0.1 0.3 0.5 0.7 1 1.5 2; do
  for w in -2 -1.5 -1 -0.5 -0.25 -0.1 0 0.1 0.25 0.5 1 1.5 2; do
    echo "$y $w $w"
  done
done

# 3) Targeted branch cases.
# r max: r > g and r > b. r = y+1.14v large -> v positive big; u near 0 keeps b near y.
#   r max, b > g  (hue needs +6 wrap): b > g  <=> 2.032u > -0.395u-0.581v <=> 2.427u + 0.581v > 0
#   r max, b <= g: 2.427u + 0.581v <= 0
#   r max, b == g boundary: u = -0.581/2.427 * v
# g max: g > r and g > b -> u,v negative.
# b max: b > r and b > g -> u positive big, v negative-ish.

# r max with b > g: v>0 (r max), u slightly positive or small negative
for y in -0.5 0 0.5 1; do
  for v in 0.2 0.5 1 1.5 2; do
    for u in 0 0.05 0.1 0.3 0.5; do
      echo "$y $u $v"
    done
  done
done

# r max with b < g: v>0, u sufficiently negative (2.427u + 0.581v < 0)
for y in -0.5 0 0.5 1; do
  for v in 0.2 0.5 1 1.5 2; do
    for u in -0.1 -0.3 -0.5 -1 -1.5; do
      # keep r max: r=y+1.14v must exceed g=y-0.395u-0.581v -> 1.14v > -0.395u-0.581v
      echo "$y $u $v"
    done
  done
done

# r max with b == g boundary: u = -(0.581/2.427)*v, v > 0 for r max
awk 'BEGIN{
  split("-0.5 0 0.25 0.5 1", ys, " ");
  split("0.1 0.3 0.7 1.2 1.9", vs, " ");
  for(i=1;i<=5;i++) for(j=1;j<=5;j++){
    v=vs[j]; u=-(0.581/2.427)*v;
    printf "%s %.10g %.10g\n", ys[i], u, v;
  }
}'

# near-boundary perturbations around b==g in r-max branch
awk 'BEGIN{
  split("0 0.5 1", ys, " ");
  split("0.4 1.0 1.6", vs, " ");
  split("-1e-6 -1e-4 -0.01 0 0.01 1e-4 1e-6", ds, " ");
  for(i=1;i<=3;i++) for(j=1;j<=3;j++) for(k=1;k<=7;k++){
    v=vs[j]; u=-(0.581/2.427)*v + ds[k];
    printf "%s %.10g %.10g\n", ys[i], u, v;
  }
}'

# g max: u,v negative (both reduce g? no: g = y -0.395u -0.581v, so u,v negative raise g)
for y in -0.5 0 0.5 1; do
  for u in -2 -1 -0.5 -0.2; do
    for v in -2 -1 -0.5 -0.2; do
      echo "$y $u $v"
    done
  done
done

# b max: u positive big, v not too positive
for y in -0.5 0 0.5 1; do
  for u in 0.3 0.5 1 1.5 2; do
    for v in -1 -0.5 -0.1 0 0.1; do
      echo "$y $u $v"
    done
  done
done

# g==r and g==b ties and near-max ties across branches (delta boundaries)
awk 'BEGIN{
  # r == g tie within r/g max: 1.14v = -0.395u - 0.581v -> u = -(1.721/0.395)v
  split("0 0.5 1", ys, " ");
  split("-0.5 0.3 0.8", vs, " ");
  for(i=1;i<=3;i++) for(j=1;j<=3;j++){
    v=vs[j]; u=-(1.721/0.395)*v;
    printf "%s %.10g %.10g\n", ys[i], u, v;
  }
  # r == b tie: 1.14v = 2.032u
  for(i=1;i<=3;i++) for(j=1;j<=3;j++){
    v=vs[j]; u=(1.14/2.032)*v;
    printf "%s %.10g %.10g\n", ys[i], u, v;
  }
}'

